from pathlib import Path
root=Path('/mnt/data/reliever_work')

p=root/'app.js'; s=p.read_text()
needle="""window._attendanceRows=a;renderStaff(s);renderProfileRecords(s);fillCreateParent(s);renderAttendance(a);renderFines(f);renderAccount(ac);$$('[data-stat]').forEach(x=>x.textContent=stats[x.dataset.stat]??0);fillTargets(s);fillAdvanceTargets(s);renderDaily(a);loadNotices();loadHelp();loadPointTransfers();loadTaskTargets();loadTasks();if(!isAdminRole)loadTransferPoints();if(isAdminRole){loadPayroll();loadReports();loadRelievers();loadPointUpdates();loadDirectTransferPoints();}if(['supervisor','officer','field_officer'].includes(role))loadTeamAttendance();}catch(e){console.log(e.message)}}\n"""
if needle not in s: raise SystemExit('refresh exact not found')
repl=needle.replace("loadTasks();", "loadTasks();loadRelieverRequests();")
s=s.replace(needle,repl,1)
marker="""// =====================================================\n\n// SECTION: FUNCTION loadRelievers\n"""
block="""// =====================================================\n// SECTION: RELIEVER REQUEST MANAGEMENT\n// =====================================================\nasync function loadRelieverRequests(){\n  const table=$('#relieverRequestRows'), mine=$('#myRelieverRequestRows');\n  if(!table&&!mine)return;\n  try{\n    const rows=await api('/reliever-requests');\n    if(table){\n      const relievers=(window._relievers||[]).filter(x=>x.status==='active'&&Number(x.is_reliever)===1);\n      table.innerHTML=rows.map(x=>{\n        const options=relievers.filter(r=>String(r.location_code||'')===String(x.location_code||'')).map(r=>`<option value=\"${escape(r.staff_id)}\">${escape(r.name)} — ${escape(r.staff_id)} — ${escape(r.location_code||'')}</option>`).join('');\n        const action=x.status==='Pending' ? `<select id=\"requestReliever_${x.id}\"><option value=\"\">Select Reliever</option>${options}</select> <button class=\"action success\" onclick=\"approveRelieverRequest(${x.id})\">✓ Approve</button> <button class=\"action danger\" onclick=\"rejectRelieverRequest(${x.id})\">✕ Reject</button>` : '—';\n        const assigned=x.reliever_id?`${escape(x.reliever_name)} (${escape(x.reliever_id)})<br><small>${escape(x.reliever_location||'—')}</small>`:'—';\n        return `<tr><td>${escape(label(x.staff_role))}</td><td>${escape(x.staff_name)}</td><td>${escape(x.staff_id)}</td><td>${escape(x.location_code)}</td><td>${escape(x.request_type)}</td><td>${escape(x.from_date)} → ${escape(x.to_date)}</td><td>${escape(x.reason)}</td><td><b>${escape(x.status)}</b></td><td>${assigned}</td><td>${action}</td></tr>`;\n      }).join('')||'<tr><td colspan=10>No reliever requests.</td></tr>';\n    }\n    if(mine){\n      mine.innerHTML=rows.map(x=>{\n        const assigned=x.reliever_id?`${escape(x.reliever_name)} (${escape(x.reliever_id)}) • ${escape(x.reliever_location||'—')}`:'Not assigned yet';\n        return `<div class=\"panel reliever-request-card\"><div><b>${escape(x.request_type)}</b> <span class=\"request-status\">${escape(x.status)}</span></div><p><b>${escape(x.from_date)} → ${escape(x.to_date)}</b> • Location: <b>${escape(x.location_code)}</b></p><p>${escape(x.reason)}</p><p>Reliever: <b>${assigned}</b></p><small>${escape(x.created_at||'')}</small></div>`;\n      }).join('')||'<p class=\"muted-note\">No requests submitted yet.</p>';\n    }\n  }catch(e){console.log('Reliever requests:',e.message)}\n}\n\nasync function approveRelieverRequest(id){\n  const sel=$('#requestReliever_'+id); const reliever_id=sel?.value||'';\n  if(!reliever_id)return alert('Select the Reliever who will cover this duty.');\n  if(!confirm('Approve this leave request and assign the selected Reliever?'))return;\n  try{const r=await api('/reliever-requests/'+id+'/approve',{method:'PUT',body:JSON.stringify({reliever_id})});msg(r.message||'Request approved ✓');loadRelieverRequests();loadRelievers();}catch(e){alert(e.message)}\n}\nasync function rejectRelieverRequest(id){\n  const reason=prompt('Optional rejection note:',''); if(reason===null)return;\n  if(!confirm('Reject this reliever request?'))return;\n  try{const r=await api('/reliever-requests/'+id+'/reject',{method:'PUT',body:JSON.stringify({reason})});msg(r.message||'Request rejected');loadRelieverRequests();}catch(e){alert(e.message)}\n}\nwindow.approveRelieverRequest=approveRelieverRequest;window.rejectRelieverRequest=rejectRelieverRequest;\n\n$('#relieverRequestForm')?.addEventListener('submit',async e=>{\n  e.preventDefault(); const d=Object.fromEntries(new FormData(e.target));\n  try{const r=await api('/reliever-requests',{method:'POST',body:JSON.stringify(d)});msg(r.message||'Request submitted ✓');e.target.reset();if($('#requestName'))$('#requestName').value=user.name||'';if($('#requestStaffId'))$('#requestStaffId').value=user.staff_id||'';if($('#requestLocation'))$('#requestLocation').value=user.location_code||'';loadRelieverRequests();}catch(err){alert(err.message)}\n});\n\n"""+marker
if marker not in s: raise SystemExit('loadRelievers marker missing')
s=s.replace(marker,block,1)
# Trigger request rendering after reliever list is loaded, so approval dropdowns have choices.
old="""    if(unselectedBox)unselectedBox.innerHTML=active.filter(x=>Number(x.is_reliever)!==1).map(rowMini).join('')||'<tr><td colspan=\"4\">No unselected members.</td></tr>';\n  }catch(e){console.log(e.message)}\n}"""
new="""    if(unselectedBox)unselectedBox.innerHTML=active.filter(x=>Number(x.is_reliever)!==1).map(rowMini).join('')||'<tr><td colspan=\"4\">No unselected members.</td></tr>';\n    loadRelieverRequests();\n  }catch(e){console.log(e.message)}\n}"""
if old not in s: raise SystemExit('reliever end missing')
s=s.replace(old,new,1)
p.write_text(s)

# Shared request section generator
def request_section(role):
    role_title='Guard' if role=='guard' else 'Supervisor'
    return f'''        <section id="reliever-request" class="view hidden">\n          <h2>♻ Reliever Request</h2>\n          <div class="panel">\n            <p class="muted-note">Holiday, illness ya emergency ke liye request bhejein. Name, Staff ID aur Location Code aapke login se automatically aayega.</p>\n            <form id="relieverRequestForm" class="grid-form">\n              <label>Full Name<input id="requestName" value="{role_title}" readonly></label>\n              <label>Staff ID<input id="requestStaffId" value="{role_title.upper()}-ID" readonly></label>\n              <label>Location Code<input id="requestLocation" name="location_code" value="" readonly></label>\n              <label>Request Type<select name="request_type" required><option value="">Select Request</option><option value="Holiday">Holiday</option><option value="Medical / Illness">Medical / Illness</option><option value="Emergency">Emergency</option></select></label>\n              <label>From Date<input type="date" name="from_date" required></label>\n              <label>To Date<input type="date" name="to_date" required></label>\n              <label style="grid-column:1/-1">Reason / Details<textarea name="reason" placeholder="Holiday reason / illness details" required></textarea></label>\n              <button class="action primary-action" type="submit">📨 Submit Reliever Request</button>\n            </form>\n          </div>\n          <div>\n            <h3>My Requests</h3>\n            <div id="myRelieverRequestRows"><p class="muted-note">Loading…</p></div>\n          </div>\n        </section>\n        <!-- END SECTION: RELIEVER REQUEST -->\n'''

for fn,role,insert_before in [('guard.html','guard','        <section id="tasks" class="view hidden">'),('supervisor.html','supervisor','        <section id="point-transfer" class="view hidden">')]:
    p=root/fn; s=p.read_text()
    nav='''        <button data-view="reliever-request">\n          ♻ Reliever Request\n        </button>\n'''
    task='''        <button data-view="tasks">\n          ✓ Task Management\n        </button>\n'''
    if 'data-view="reliever-request"' not in s:
        s=s.replace(task,nav+task,1)
    if 'id="reliever-request"' not in s:
        s=s.replace(insert_before,request_section(role)+insert_before,1)
    p.write_text(s)

# Admin sidebar + section
p=root/'admin.html'; s=p.read_text()
nav='''        <button data-view="reliever-requests">\n          📨 Reliever Requests\n        </button>\n'''
if 'data-view="reliever-requests"' not in s:
    s=s.replace('''        <button data-view="point-updates">''',nav+'''        <button data-view="point-updates">''',1)
section='''        <section id="reliever-requests" class="view hidden">\n          <h2>📨 Reliever Requests</h2>\n          <div class="panel">\n            <p class="muted-note">Guard/Supervisor ki Holiday, Medical / Illness aur Emergency requests yahan aayengi. Approve karne se pehle same Location Code ka active Reliever select karein. Approval ke baad requester aur Reliever dono ko in-app notification/WhatsApp notification milne ki koshish hogi.</p>\n            <div class="table-wrap">\n              <table>\n                <thead><tr><th>Role</th><th>Name</th><th>ID</th><th>Location</th><th>Request</th><th>From → To</th><th>Reason</th><th>Status</th><th>Reliever</th><th>Action</th></tr></thead>\n                <tbody id="relieverRequestRows"><tr><td colspan="10">Loading…</td></tr></tbody>\n              </table>\n            </div>\n          </div>\n        </section>\n        <!-- END SECTION: RELIEVER REQUESTS -->\n'''
if 'id="reliever-requests"' not in s:
    s=s.replace('''        <section id="point-updates" class="view hidden">''',section+'''        <section id="point-updates" class="view hidden">''',1)
p.write_text(s)

