css='''\n/* RELIEVER REQUESTS */\n.reliever-request-card{margin-bottom:12px;border-left:4px solid var(--blue);}\n.request-status{display:inline-block;padding:4px 9px;border-radius:999px;background:#eef7ff;margin-left:8px;font-size:12px;}\n#relieverRequestRows select{min-width:180px;}\n@media(max-width:700px){#relieverRequestRows select{min-width:150px;width:100%;margin-bottom:6px;}.reliever-request-card{padding:14px;}}\n'''
